23: #define BLOCK_SIZE 512
24: #define ILP 4
25: 
26: typedef enum : int {
27:     ADAM_MODE_0 = 0,  // L2 regularization mode
28:     ADAM_MODE_1 = 1   // Decoupled weight decay mode(AdamW)
29: } adamMode_t;
30: 
31: using MATH_T = float;
32: 
33: template <typename T, typename index_t>
34: struct AdamFunctor {
35:     __device__ __forceinline__ void operator()(int chunk_size,
36:                                                volatile int* noop_gmem,
37:                                                TensorListMetadata<4>& tl,
38:                                                const float beta1,
39:                                                const float beta2,
40:                                                const float beta1_correction,
41:                                                const float beta2_correction,
42:                                                const float epsilon,
43:                                                const float lr,
44:                                                adamMode_t mode,
45:                                                const float decay)
46:     {
47:         // I'd like this kernel to propagate infs/nans.
48:         // if(*noop_gmem == 1)
49:         //   return;
50: 
51:         index_t tensor_loc = tl.block_to_tensor[blockIdx.x];
52: 
53:         // potentially use to pass in list of scalar
54:         // int tensor_num = tl.start_tensor_this_launch + tensor_loc;
55: 
56:         index_t chunk_idx = tl.block_to_chunk[blockIdx.x];
57:         index_t n = tl.sizes[tensor_loc];
58: 
59:         T* g = (T*)tl.addresses[0][tensor_loc];
60:         g += chunk_idx * chunk_size;
61: 
62:         T* p = (T*)tl.addresses[1][tensor_loc];
63:         p += chunk_idx * chunk_size;
64: 
65:         T* m = (T*)tl.addresses[2][tensor_loc];
66:         m += chunk_idx * chunk_size;
67: 
68:         T* v = (T*)tl.addresses[3][tensor_loc];
69:         v += chunk_idx * chunk_size;
70: 
71:         n -= chunk_idx * chunk_size;
72: 
73:         // see note in multi_tensor_scale_kernel.cu
74:         for (index_t i_start = 0; i_start < n && i_start < chunk_size;
75:              i_start += blockDim.x * ILP) {
76:             MATH_T r_g[ILP];
77:             MATH_T r_p[ILP];
78:             MATH_T r_m[ILP];
79:             MATH_T r_v[ILP];
80: #pragma unroll
81:             for (int ii = 0; ii < ILP; ii++) {
82:                 int i = i_start + threadIdx.x + ii * blockDim.x;
83:                 if (i < n && i < chunk_size) {
84:                     r_g[ii] = g[i];
85:                     r_p[ii] = p[i];
86:                     r_m[ii] = m[i];
87:                     r_v[ii] = v[i];
88:                 } else {
89:                     r_g[ii] = MATH_T(0);
90:                     r_p[ii] = MATH_T(0);
91:                     r_m[ii] = MATH_T(0);
92:                     r_v[ii] = MATH_T(0);
93:                 }
94:             }
95: #pragma unroll
96:             for (int ii = 0; ii < ILP; ii++) {
97:                 if (mode == ADAM_MODE_0) {  // L2
98:                     r_g[ii] = r_g[ii] + (decay * r_p[ii]);
99:                     r_m[ii] = beta1 * r_m[ii] + (1 - beta1) * r_g[ii];
100:                     r_v[ii] = beta2 * r_v[ii] + (1 - beta2) * r_g[ii] * r_g[ii];
101:                     MATH_T next_m_unbiased = r_m[ii] / beta1_correction;
102:                     MATH_T next_v_unbiased = r_v[ii] / beta2_correction;
103:                     MATH_T denom = sqrtf(next_v_unbiased) + epsilon;
104:                     MATH_T update = next_m_unbiased / denom;
105:                     r_p[ii] = r_p[ii] - (lr * update);
106:                 } else {  // weight decay
107:                     r_m[ii] = beta1 * r_m[ii] + (1 - beta1) * r_g[ii];
108:                     r_v[ii] = beta2 * r_v[ii] + (1 - beta2) * r_g[ii] * r_g[ii];
109:                     MATH_T next_m_unbiased = r_m[ii] / beta1_correction;
110:                     MATH_T next_v_unbiased = r_v[ii] / beta2_correction;
111:                     MATH_T denom = sqrtf(next_v_unbiased) + epsilon;
112:                     MATH_T update = (next_m_unbiased / denom) + (decay * r_p[ii]);
113:                     r_p[ii] = r_p[ii] - (lr * update);
114:                 }
115:             }
116: #pragma unroll
117:             for (int ii = 0; ii < ILP; ii++) {
118:                 int i = i_start + threadIdx.x + ii * blockDim.x;
119:                 if (i < n && i < chunk_size) {
120:                     p[i] = r_p[ii];
121:                     m[i] = r_m[ii];
122:                     v[i] = r_v[ii];
123:                 }
124:             }
125:         }
126:     }
127: };
