25: constexpr int depth_to_max_tensors[5] = {110, 64, 48, 36, 30};
26: constexpr int depth_to_max_blocks[5] = {320, 320, 320, 320, 320};
27: 
28: template <int n>
29: struct TensorListMetadata {
30:     void* addresses[n][depth_to_max_tensors[n - 1]];
31:     int64_t sizes[depth_to_max_tensors[n - 1]];
32:     unsigned char block_to_tensor[depth_to_max_blocks[n - 1]];
33:     int block_to_chunk[depth_to_max_blocks[n - 1]];  // I fear this needs to be a full int.
34:     int start_tensor_this_launch;
35: };
